 public void onCreate(Bundle b){super.onCreate(b);de=java.util.Locale.getDefault().getLanguage().equals("de");ScrollView s=new ScrollView(this);s.setBackgroundColor(0xff081426);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(24),dp(24),dp(24),dp(24));s.addView(l);setContentView(s);s.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});s.requestApplyInsets();label(l,"TETHERLUME",16);label(l,t("Dein Smartphone.\nDein PC.","Your phone.\nYour PC."),34);status=label(l,"",18);label(l,t("1. USB-Datenkabel anschließen\n2. USB-Debugging aktivieren\n3. scrcpy am PC starten und RSA-Freigabe bestätigen.","1. Connect a USB data cable\n2. Enable USB debugging\n3. Start scrcpy on your PC and approve the RSA prompt."),17);button(l,t("Entwickleroptionen öffnen","Open developer options"),()->openSettings(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS));button(l,t("Geräteinformationen","About phone"),()->openSettings(Settings.ACTION_DEVICE_INFO_SETTINGS));button(l,t("Windows-Produktseite","Windows product page"),()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://marcelmolitor.github.io/android-desk/")));}catch(ActivityNotFoundException e){Toast.makeText(this,t("Kein Browser verfügbar","No browser available"),Toast.LENGTH_SHORT).show();}});label(l,t("Falls Entwickleroptionen fehlen: siebenmal auf die Build-Nummer tippen. USB-Debugging nur an vertrauenswürdigen PCs erlauben und nach Gebrauch deaktivieren. Diese App prüft keine ADB-Verbindung und spiegelt nicht selbst.","If developer options are missing, tap Build number seven times. Allow USB debugging only on trusted PCs and disable it after use. This app does not verify ADB connections or mirror the screen itself."),15);refresh();}
