 void button(LinearLayout l,String text,Runnable action){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTextColor(Color.WHITE);GradientDrawable g=new GradientDrawable();g.setColor(0xff2469d9);g.setCornerRadius(dp(16));b.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);b.setMinHeight(dp(56));p.bottomMargin=dp(12);l.addView(b,p);b.setOnClickListener(v->action.run());}
